class StatRoyxat(list):
    def ortacha(self):
        return sum(self) / len(self) if self else 0

    def mediana(self):
        b = sorted(self)
        n = len(b)
        if n % 2:
            return b[n // 2]
        return (b[n // 2 - 1] + b[n // 2]) / 2

