import re


def katak(manzil):
    m = re.fullmatch(r'([A-Z]+)([1-9]\d*)', manzil.upper())
    if not m:
        raise ValueError(manzil)
    n = 0
    for h in m.group(1):
        n = n * 26 + ord(h) - 64
    return (int(m.group(2)), n)

import re


def summa(jadval, oraliq):
    def tahlil(m):
        h, r = re.fullmatch(r'([A-Z]+)(\d+)', m).groups()
        n = 0
        for c in h:
            n = n * 26 + ord(c) - 64
        return int(r), n
    def harf(n):
        s = ''
        while n:
            n, q = divmod(n - 1, 26)
            s = chr(65 + q) + s
        return s
    a, b = oraliq.split(':')
    (r1, c1), (r2, c2) = tahlil(a), tahlil(b)
    return sum(jadval.get(f'{harf(c)}{r}', 0) for r in range(r1, r2 + 1) for c in range(c1, c2 + 1))

