import re

BLOK = r'\{% block (\w+) %\}(.*?)\{% endblock %\}'


def meros(bola, ota):
    bloklar = dict(re.findall(BLOK, bola, re.S))

    def almash(m):
        if m.group(1) not in bloklar:
            return m.group(2)
        return bloklar[m.group(1)].replace('{{ block.super }}', m.group(2))
    return re.sub(BLOK, almash, ota, flags=re.S)

