import re


def namuna(yol):
    turlar = {'int': '[0-9]+', 'str': '[^/]+', 'slug': '[-a-zA-Z0-9_]+'}
    return '^' + re.sub(r'<(?:(\w+):)?(\w+)>', lambda m: f'(?P<{m.group(2)}>{turlar[m.group(1) or "str"]})', yol) + '$'

import re


def moslashtir(yol, url):
    k = {'int': ('[0-9]+', int), 'str': ('[^/]+', str), 'slug': ('[-a-zA-Z0-9_]+', str)}
    turlar = {}

    def almash(m):
        tur = m.group(1) or 'str'
        turlar[m.group(2)] = k[tur][1]
        return f'(?P<{m.group(2)}>{k[tur][0]})'
    m = re.match('^' + re.sub(r'<(?:(\w+):)?(\w+)>', almash, yol) + '$', url)
    return {n: turlar[n](v) for n, v in m.groupdict().items()} if m else None

import re


def router(urlpatterns, url):
    k = {'int': ('[0-9]+', int), 'slug': ('[-a-zA-Z0-9_]+', str)}
    for yol, nom in urlpatterns:
        turlar = {}

        def almash(m):
            turlar[m.group(2)] = k[m.group(1)][1]
            return f'(?P<{m.group(2)}>{k[m.group(1)][0]})'
        m = re.match('^' + re.sub(r'<(\w+):(\w+)>', almash, yol) + '$', url)
        if m:
            return nom, {n: turlar[n](v) for n, v in m.groupdict().items()}
    return '404', {}

import re


def reverse(urlpatterns, nom, **kw):
    for yol, n in urlpatterns:
        if n == nom:
            try:
                return '/' + re.sub(r'<(?:\w+:)?(\w+)>', lambda m: str(kw[m.group(1)]), yol)
            except KeyError:
                break
    raise LookupError(f'NoReverseMatch: {nom}')

