from datetime import date
from decimal import Decimal


def serialize(obyekt, maydonlar):
    d = {}
    for m in maydonlar:
        v = obyekt[m]
        if isinstance(v, date):
            v = v.isoformat()
        elif isinstance(v, Decimal):
            v = str(v)
        d[m] = v
    return d

