import math


def sahifala(elementlar, sahifa, hajm=10):
    jami = max(1, math.ceil(len(elementlar) / hajm))
    if not 1 <= sahifa <= jami:
        raise ValueError('Notoʻgʻri sahifa')
    return {'count': len(elementlar), 'next': sahifa + 1 if sahifa < jami else None,
            'previous': sahifa - 1 if sahifa > 1 else None, 'results': elementlar[(sahifa - 1) * hajm: sahifa * hajm]}

