import re


def api(metod, yol, baza):
    if yol == '/api/kitoblar/' and metod == 'GET':
        return 200, [k['id'] for k in baza]
    m = re.fullmatch(r'/api/kitoblar/(\d+)/', yol)
    if m and metod in ('GET', 'DELETE'):
        k = next((k for k in baza if k['id'] == int(m.group(1))), None)
        if k is None:
            return 404, {'xato': 'Topilmadi'}
        return (200, k) if metod == 'GET' else (204, None)
    return 405, {'xato': 'Ruxsat etilmagan'}

